#define TS_LEX_ADVANCE_MAP_SORTED(map)                                      \
  {                                                                 \
    uint32_t low = 0;                                                \
    uint32_t high = sizeof(map) / sizeof(map[0]) / 2;                 \
    while (low < high) {                                             \
      uint32_t mid = low + (high - low) / 2;                          \
      if (map[mid * 2] < lookahead) {                                \
